#include "../../BaseTest.Bridge.h"

// forward declarations - TS hoists function declarations, C++ does not
void testDecimalToPrecision();

void testDecimalToPrecision()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("regirock") },
    });
    // ----------------------------------------------------------------------------
    // Truncate To N Digits After Dot
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456000"), TRUNCATE, 100, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 100, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 4, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 3, DECIMAL_PLACES), std::string("12.345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 2, DECIMAL_PLACES), std::string("12.34")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 1, DECIMAL_PLACES), std::string("12.3")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, 0, DECIMAL_PLACES), std::string("12")));
    // ['12.3456',    TRUNCATE,  -1, DECIMAL_PLACES,  '10'],   // not yet supported
    // ['123.456',    TRUNCATE,  -2, DECIMAL_PLACES,  '120'],  // not yet supported
    // ['123.456',    TRUNCATE,  -3, DECIMAL_PLACES,  '100'],  // not yet supported
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0000001"), TRUNCATE, 8, DECIMAL_PLACES), std::string("0.0000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00000001"), TRUNCATE, 8, DECIMAL_PLACES), std::string("0.00000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000000000"), TRUNCATE, 9, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("0.000000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000000001"), TRUNCATE, 9, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("0.000000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), TRUNCATE, -1, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.456"), TRUNCATE, -1, DECIMAL_PLACES), std::string("120")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.456"), TRUNCATE, -2, DECIMAL_PLACES), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.99999"), TRUNCATE, -1, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.9999"), TRUNCATE, -1, DECIMAL_PLACES), std::string("90")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.9999"), TRUNCATE, -2, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0"), TRUNCATE, 0, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.9"), TRUNCATE, 0, DECIMAL_PLACES), std::string("0")));
    // ----------------------------------------------------------------------------
    // Truncate To N Significant Digits
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456700"), TRUNCATE, 100, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), TRUNCATE, 100, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), TRUNCATE, 7, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), TRUNCATE, 6, SIGNIFICANT_DIGITS), std::string("0.000123456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), TRUNCATE, 5, SIGNIFICANT_DIGITS), std::string("0.00012345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), TRUNCATE, 2, SIGNIFICANT_DIGITS), std::string("0.00012")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), TRUNCATE, 1, SIGNIFICANT_DIGITS), std::string("0.0001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 10, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("123.0000987")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 8, SIGNIFICANT_DIGITS), std::string("123.00009")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 7, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("123.0000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 6, SIGNIFICANT_DIGITS), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 5, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("123.00")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 4, SIGNIFICANT_DIGITS), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 4, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("123.0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 3, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 2, SIGNIFICANT_DIGITS), std::string("120")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 1, SIGNIFICANT_DIGITS), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), TRUNCATE, 1, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234"), TRUNCATE, 5, SIGNIFICANT_DIGITS), std::string("1234")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234"), TRUNCATE, 5, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("1234.0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234"), TRUNCATE, 4, SIGNIFICANT_DIGITS), std::string("1234")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234"), TRUNCATE, 4, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("1234")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234.69"), TRUNCATE, 0, SIGNIFICANT_DIGITS), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1234.69"), TRUNCATE, 0, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("0")));
    // ----------------------------------------------------------------------------
    // Round To N Digits After Dot
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456000"), ROUND, 100, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 100, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 4, DECIMAL_PLACES), std::string("12.3456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 3, DECIMAL_PLACES), std::string("12.346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 2, DECIMAL_PLACES), std::string("12.35")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 1, DECIMAL_PLACES), std::string("12.3")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, 0, DECIMAL_PLACES), std::string("12")));
    // todo:
    // ['9.999',     ROUND,   3, DECIMAL_PLACES,    NO_PADDING,  '9.999'],
    // ['9.999',     ROUND,   2, DECIMAL_PLACES,    NO_PADDING,  '10'],
    // ['9.999',     ROUND,   2, DECIMAL_PLACES, PAD_WITH_ZERO,  '10.00'],
    // ['99.999',    ROUND,   2, DECIMAL_PLACES, PAD_WITH_ZERO,  '100.00'],
    // ['-99.999',    ROUND,   2, DECIMAL_PLACES, PAD_WITH_ZERO, '-100.00'],
    // ['12.3456',    ROUND,  -1, DECIMAL_PLACES,    NO_PADDING,  '10'],  // not yet supported
    // ['123.456',    ROUND,  -1, DECIMAL_PLACES,    NO_PADDING,  '120'],  // not yet supported
    // ['123.456',    ROUND,  -2, DECIMAL_PLACES,    NO_PADDING,  '100'],  // not yet supported
    // a problematic case in PHP
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("10000"), ROUND, 6, DECIMAL_PLACES), std::string("10000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00003186"), ROUND, 8, DECIMAL_PLACES), std::string("0.00003186")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.3456"), ROUND, -1, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.456"), ROUND, -1, DECIMAL_PLACES), std::string("120")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.456"), ROUND, -2, DECIMAL_PLACES), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.99999"), ROUND, -1, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.9999"), ROUND, -1, DECIMAL_PLACES), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.9999"), ROUND, -2, DECIMAL_PLACES), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999"), ROUND, 3, DECIMAL_PLACES), std::string("9.999")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999"), ROUND, 2, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999"), ROUND, 2, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("10.00")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.999"), ROUND, 2, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("100.00")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-99.999"), ROUND, 2, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("-100.00")));
    // ----------------------------------------------------------------------------
    // Round To N Significant Digits
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456700"), ROUND, 100, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), ROUND, 100, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), ROUND, 7, SIGNIFICANT_DIGITS), std::string("0.0001234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), ROUND, 6, SIGNIFICANT_DIGITS), std::string("0.000123456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("0.00012346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456"), ROUND, 4, SIGNIFICANT_DIGITS), std::string("0.0001235")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00012"), ROUND, 2, SIGNIFICANT_DIGITS), std::string("0.00012")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001"), ROUND, 1, SIGNIFICANT_DIGITS), std::string("0.0001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), ROUND, 7, SIGNIFICANT_DIGITS), std::string("123.0001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123.0000987654"), ROUND, 6, SIGNIFICANT_DIGITS), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00098765"), ROUND, 2, SIGNIFICANT_DIGITS), std::string("0.00099")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00098765"), ROUND, 2, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("0.00099")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00098765"), ROUND, 1, SIGNIFICANT_DIGITS), std::string("0.001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00098765"), ROUND, 10, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("0.0009876500000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.098765"), ROUND, 1, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("0.1")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0"), ROUND, 0, SIGNIFICANT_DIGITS), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.123"), ROUND, 0, SIGNIFICANT_DIGITS), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00000044"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("0.00000044")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.123456"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("0.12346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.123456"), ROUND, 6, SIGNIFICANT_DIGITS), std::string("0.123456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.123456"), ROUND, 7, SIGNIFICANT_DIGITS), std::string("0.123456")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.234567"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("1.2346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.234567"), ROUND, 6, SIGNIFICANT_DIGITS), std::string("1.23457")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.234567"), ROUND, 7, SIGNIFICANT_DIGITS), std::string("1.234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.34567"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("12.346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.34567"), ROUND, 6, SIGNIFICANT_DIGITS), std::string("12.3457")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12.34567"), ROUND, 7, SIGNIFICANT_DIGITS), std::string("12.34567")));
    // above 1.0
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1114.5"), ROUND, 3, SIGNIFICANT_DIGITS), std::string("1110")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1115.5"), ROUND, 3, SIGNIFICANT_DIGITS), std::string("1120")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1114.5"), ROUND, 4, SIGNIFICANT_DIGITS), std::string("1115")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1114.5"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("1114.5")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1115.5"), ROUND, 5, SIGNIFICANT_DIGITS), std::string("1115.5")));
    // ----------------------------------------------------------------------------
    // Round To Tick Size
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456700"), ROUND, 0.00012, TICK_SIZE), std::string("0.00012")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), ROUND, 0.00013, TICK_SIZE), std::string("0.00013")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0001234567"), TRUNCATE, 0.00013, TICK_SIZE), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("101.000123456700"), ROUND, 100, TICK_SIZE), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456700"), ROUND, 100, TICK_SIZE), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("165"), TRUNCATE, 110, TICK_SIZE), std::string("110")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("3210"), TRUNCATE, 1110, TICK_SIZE), std::string("2220")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("165"), ROUND, 110, TICK_SIZE), std::string("220")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456789"), ROUND, 1.2e-7, TICK_SIZE), std::string("0.00012348")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456789"), TRUNCATE, 1.2e-7, TICK_SIZE), std::string("0.00012336")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000273398"), ROUND, 1e-7, TICK_SIZE), std::string("0.0002734")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00005714"), TRUNCATE, 1e-8, TICK_SIZE), std::string("0.00005714")));
    // this line causes problems in JS, fix with Precise
    // assert (exchange.decimalToPrecision ('0.0000571495257361', TRUNCATE, 0.00000001, TICK_SIZE) === '0.00005714');
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.01"), ROUND, 0.0001, TICK_SIZE, PAD_WITH_ZERO), std::string("0.0100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.01"), TRUNCATE, 0.0001, TICK_SIZE, PAD_WITH_ZERO), std::string("0.0100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.000123456789"), ROUND, 1.2e-7, TICK_SIZE), std::string("-0.00012348")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.000123456789"), TRUNCATE, 1.2e-7, TICK_SIZE), std::string("-0.00012336")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-165"), TRUNCATE, 110, TICK_SIZE), std::string("-110")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-165"), ROUND, 110, TICK_SIZE), std::string("-220")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-1650"), TRUNCATE, 1100, TICK_SIZE), std::string("-1100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-1650"), ROUND, 1100, TICK_SIZE), std::string("-2200")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0006"), TRUNCATE, 0.0001, TICK_SIZE), std::string("0.0006")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.0006"), TRUNCATE, 0.0001, TICK_SIZE), std::string("-0.0006")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.6"), TRUNCATE, 0.2, TICK_SIZE), std::string("0.6")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.6"), TRUNCATE, 0.2, TICK_SIZE), std::string("-0.6")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.2"), ROUND, 0.4, TICK_SIZE), std::string("1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-1.2"), ROUND, 0.4, TICK_SIZE), std::string("-1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.2"), ROUND, 0.02, TICK_SIZE), std::string("1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-1.2"), ROUND, 0.02, TICK_SIZE), std::string("-1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("44"), ROUND, 4.4, TICK_SIZE), std::string("44")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-44"), ROUND, 4.4, TICK_SIZE), std::string("-44")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("44.00000001"), ROUND, 4.4, TICK_SIZE), std::string("44")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-44.00000001"), ROUND, 4.4, TICK_SIZE), std::string("-44")));
    // https://github.com/ccxt/ccxt/issues/6731
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("20"), TRUNCATE, 1e-8, TICK_SIZE), std::string("20")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.000123456789"), TRUNCATE, 1e-8, TICK_SIZE), std::string("0.00012345")));
    // ----------------------------------------------------------------------------
    // Negative Numbers
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.123456"), TRUNCATE, 5, DECIMAL_PLACES), std::string("-0.12345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.123456"), ROUND, 5, DECIMAL_PLACES), std::string("-0.12346")));
    // ----------------------------------------------------------------------------
    // without dot / trailing dot
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123"), TRUNCATE, 0), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123"), TRUNCATE, 5, DECIMAL_PLACES), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123"), TRUNCATE, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("123.00000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123."), TRUNCATE, 0, DECIMAL_PLACES), std::string("123")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123."), TRUNCATE, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("123.00000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0."), TRUNCATE, 0), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0."), TRUNCATE, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("0.00000")));
    // ----------------------------------------------------------------------------
    // rounding for equidistant digits
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.44"), ROUND, 1, DECIMAL_PLACES), std::string("1.4")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.45"), ROUND, 1, DECIMAL_PLACES), std::string("1.5")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.45"), ROUND, 0, DECIMAL_PLACES), std::string("1"))); // not 2
    // ----------------------------------------------------------------------------
    // negative precision only implemented so far in python
    // pretty useless for decimal applications as anything |x| < 5 === 0
    // NO_PADDING and PAD_WITH_ZERO are ignored
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("5"), ROUND, -1, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("4.999"), ROUND, -1, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0431531423"), ROUND, -1, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-69.3"), ROUND, -1, DECIMAL_PLACES), std::string("-70")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("5001"), ROUND, -4, DECIMAL_PLACES), std::string("10000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("4999.999"), ROUND, -4, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("69.3"), TRUNCATE, -2, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-69.3"), TRUNCATE, -2, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("69.3"), TRUNCATE, -1, SIGNIFICANT_DIGITS), std::string("60")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-69.3"), TRUNCATE, -1, SIGNIFICANT_DIGITS), std::string("-60")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("69.3"), TRUNCATE, -2, SIGNIFICANT_DIGITS), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1602000000000000000000"), TRUNCATE, 3, SIGNIFICANT_DIGITS), std::string("1600000000000000000000")));
    // ----------------------------------------------------------------------------
    // stringified precision
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.000123456789"), ROUND, std::string("0.00000012"), TICK_SIZE), std::string("-0.00012348")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.000123456789"), TRUNCATE, std::string("0.00000012"), TICK_SIZE), std::string("-0.00012336")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-165"), TRUNCATE, std::string("110"), TICK_SIZE), std::string("-110")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-165"), ROUND, std::string("110"), TICK_SIZE), std::string("-220")));
    // ----------------------------------------------------------------------------
    // testDecimalToPrecisionErrorHandling (todo)
    //
    // throws (() =>
    //     decimalToPrecision ('123456.789', TRUNCATE, -2, DECIMAL_PLACES),
    //         'negative precision is not yet supported')
    //
    // throws (() =>
    //     decimalToPrecision ('foo'),
    //         "invalid number (contains an illegal character 'f')")
    //
    // throws (() =>
    //     decimalToPrecision ('0.01', TRUNCATE, -1, TICK_SIZE),
    //         "TICK_SIZE cant be used with negative numPrecisionDigits")
    // ----------------------------------------------------------------------------
    // Additional Edge Cases
    // Zero handling variations
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0"), TRUNCATE, 2, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00"), ROUND, 3, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("0.000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.0"), TRUNCATE, 2, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-0.00"), ROUND, 1, DECIMAL_PLACES), std::string("0")));
    // Very small numbers close to zero
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0000000001"), TRUNCATE, 8, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0000000001"), ROUND, 8, DECIMAL_PLACES), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.0000000001"), TRUNCATE, 10, DECIMAL_PLACES), std::string("0.0000000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00000000009"), ROUND, 10, DECIMAL_PLACES), std::string("0.0000000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.00000000015"), ROUND, 10, DECIMAL_PLACES), std::string("0.0000000002")));
    // Very large numbers
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99999999999999.99999"), TRUNCATE, 2, DECIMAL_PLACES), std::string("99999999999999.99")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99999999999999.99999"), ROUND, 2, DECIMAL_PLACES), std::string("100000000000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456789012345"), TRUNCATE, 3, SIGNIFICANT_DIGITS), std::string("123000000000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456789012345"), ROUND, 3, SIGNIFICANT_DIGITS), std::string("123000000000000")));
    // Numbers with leading zeros
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("000123.456"), TRUNCATE, 2, DECIMAL_PLACES), std::string("123.45")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("000123.456"), ROUND, 2, DECIMAL_PLACES), std::string("123.46")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0000.123"), TRUNCATE, 2, DECIMAL_PLACES), std::string("0.12")));
    // Boundary rounding cases (exactly at 0.5)
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.5"), ROUND, 0, DECIMAL_PLACES), std::string("2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("2.5"), ROUND, 0, DECIMAL_PLACES), std::string("3")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-1.5"), ROUND, 0, DECIMAL_PLACES), std::string("-2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-2.5"), ROUND, 0, DECIMAL_PLACES), std::string("-3")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.25"), ROUND, 1, DECIMAL_PLACES), std::string("1.3")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.35"), ROUND, 1, DECIMAL_PLACES), std::string("1.4")));
    // Carry-over in rounding (cascading effects)
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999999"), ROUND, 0, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("99.999999"), ROUND, 0, DECIMAL_PLACES), std::string("100")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("999.999999"), ROUND, 0, DECIMAL_PLACES), std::string("1000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999999"), ROUND, 1, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("9.999999"), ROUND, 2, DECIMAL_PLACES), std::string("10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-9.999999"), ROUND, 0, DECIMAL_PLACES), std::string("-10")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("-99.999999"), ROUND, 0, DECIMAL_PLACES), std::string("-100")));
    // Edge cases for TICK_SIZE with very small ticks
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.2345"), ROUND, 0.0001, TICK_SIZE), std::string("1.2345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.23456"), ROUND, 0.0001, TICK_SIZE), std::string("1.2346")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.23454"), ROUND, 0.0001, TICK_SIZE), std::string("1.2345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.23444"), TRUNCATE, 0.0001, TICK_SIZE), std::string("1.2344")));
    // TICK_SIZE with numbers smaller than tick
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.05"), ROUND, 0.1, TICK_SIZE), std::string("0.1")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.04"), ROUND, 0.1, TICK_SIZE), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.04"), TRUNCATE, 0.1, TICK_SIZE), std::string("0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.049999"), ROUND, 0.1, TICK_SIZE), std::string("0")));
    // SIGNIFICANT_DIGITS edge cases
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("10000000"), TRUNCATE, 1, SIGNIFICANT_DIGITS), std::string("10000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("10000001"), TRUNCATE, 1, SIGNIFICANT_DIGITS), std::string("10000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("19999999"), TRUNCATE, 1, SIGNIFICANT_DIGITS), std::string("10000000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("19999999"), ROUND, 1, SIGNIFICANT_DIGITS), std::string("20000000")));
    // Precision with PAD_WITH_ZERO edge cases
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1"), TRUNCATE, 0, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.0"), TRUNCATE, 0, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1"), TRUNCATE, 3, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1.000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.1"), TRUNCATE, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1.10000")));
    // Numbers that are exactly multiples of precision
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.2"), TRUNCATE, 0.1, TICK_SIZE), std::string("1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.2"), ROUND, 0.1, TICK_SIZE), std::string("1.2")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12"), TRUNCATE, 4, TICK_SIZE), std::string("12")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("12"), ROUND, 4, TICK_SIZE), std::string("12")));
    // Very high precision values
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.123456789012345"), TRUNCATE, 15, DECIMAL_PLACES), std::string("1.123456789012345")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.123456789012345"), TRUNCATE, 10, DECIMAL_PLACES), std::string("1.123456789")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1.123456789012345"), TRUNCATE, 10, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1.1234567890")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.123456789012345"), TRUNCATE, 15, SIGNIFICANT_DIGITS), std::string("0.123456789012345")));
    // Mixed large and small components
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1000000.000001"), TRUNCATE, 6, DECIMAL_PLACES), std::string("1000000.000001")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1000000.000001"), TRUNCATE, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1000000.00000")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("1000000.000001"), ROUND, 5, DECIMAL_PLACES, PAD_WITH_ZERO), std::string("1000000.00000")));
    // Edge cases around 1.0 boundary for significant digits
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.999999"), ROUND, 1, SIGNIFICANT_DIGITS), std::string("1")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.999999"), ROUND, 2, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("1.0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.999999"), ROUND, 3, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("1.00")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.999949"), ROUND, 4, SIGNIFICANT_DIGITS), std::string("0.9999")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("0.999951"), ROUND, 4, SIGNIFICANT_DIGITS, PAD_WITH_ZERO), std::string("1.000")));
    // ----------------------------------------------------------------------------
    // https://github.com/ccxt/ccxt/issues/11765
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.12345678912"), TRUNCATE, 1e-8, TICK_SIZE), std::string("123456.12345678")));
    // todo: not sure about below
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.12345674999"), TRUNCATE, 5e-8, TICK_SIZE), std::string("123456.1234567")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.12345674999"), TRUNCATE, 5e-8, TICK_SIZE, PAD_WITH_ZERO), std::string("123456.12345670")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.12345675001"), TRUNCATE, 5e-8, TICK_SIZE), std::string("123456.12345675")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.50000000001"), TRUNCATE, 0.5, TICK_SIZE, PAD_WITH_ZERO), std::string("123456.5")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.49999999999"), TRUNCATE, 0.5, TICK_SIZE, PAD_WITH_ZERO), std::string("123456.0")));
    assertTrue(isEqual(exchange.decimalToPrecision(std::string("123456.12345678912"), TRUNCATE, std::string("0.00000001"), TICK_SIZE), std::string("123456.12345678")));
}

